type LoadState =
  | { status: 'loading' }
  | { status: 'loaded'; items: string[] }
  | { status: 'failed'; error: string };

function render(state: LoadState): string {
  switch (state.status) {
    case 'loading': return 'Loading...';
    case 'loaded':  return `${state.items.length} items`;
    case 'failed':  return `Error: ${state.error}`;
    default: {
      const unhandled: never = state;
      return unhandled;
    }
  }
}

console.log(render({ status: 'loaded', items: ['Math', 'Databases'] }));
console.log(render({ status: 'failed', error: 'timeout' }));

