function parseGrade(text: string): number {
  const grade = Number(text);
  if (!Number.isInteger(grade) || grade < 0 || grade > 100)
    throw new Error(`"${text}" is not a grade between 0 and 100`);
  return grade;
}

for (const input of ['85', 'abc', '120']) {
  try {
    console.log(parseGrade(input));
  } catch (err) {
    console.log(err instanceof Error ? err.message : String(err));
  }
}

class NotFoundError extends Error {
  constructor(what: string) {
    super(`${what} was not found`);
    this.name = 'NotFoundError';
  }
}

function findCourse(id: number): string {
  if (id !== 1) throw new NotFoundError(`Course ${id}`);
  return 'Programming';
}

try {
  findCourse(9);
} catch (err) {
  if (err instanceof NotFoundError) console.log(`404: ${err.message}`);
  else throw err;
}

type Result<T> = { ok: true; value: T } | { ok: false; error: string };

function parseYear(text: string): Result<number> {
  const year = Number(text);
  return year >= 1 && year <= 4 && Number.isInteger(year)
    ? { ok: true, value: year }
    : { ok: false, error: 'Year must be 1, 2, 3 or 4' };
}

for (const input of ['2', '7']) {
  const result = parseYear(input);
  console.log(result.ok ? `year ${result.value}` : result.error);
}
